5	// Versioning contract: proto3 additive-only.
6	// Never remove or rename fields. Ingest accepts v1+ with defaults.
7	
8	message EventBatch {
9	  string cli_version = 1;
10	  string machine_id = 2;
11	  repeated Event events = 3;
12	}
13	
14	message Event {
15	  string id = 1;
16	  int64 timestamp_ms = 2;
17	  string session_id = 3;
18	  string project_dir = 4;
19	  string command = 5;
20	  EventType event_type = 6;
21	  CompressionEvent compression = 7;
22	  DedupEvent dedup = 8;
23	}
24	
25	enum EventType {
26	  EVENT_TYPE_UNSPECIFIED = 0;
27	  EVENT_TYPE_COMPRESSION = 1;
28	  EVENT_TYPE_DEDUP = 2;
29	}
30	
31	message CompressionEvent {
32	  uint64 input_bytes = 1;
33	  uint64 output_bytes = 2;
34	  uint64 input_tokens = 3;
35	  uint64 output_tokens = 4;
36	  uint64 tokens_saved = 5;
37	  string filter_name = 6;
38	  string compression_level = 7;
39	  double latency_ms = 8;
40	}
41	
42	message DedupEvent {
43	  string content_hash = 1;
44	  bool cache_hit = 2;
45	  uint64 tokens_saved = 3;
46	  string file_path = 4;
47	  double latency_ms = 5;
48	}
