1	use anyhow::Result;
2	use rusqlite::{params, Connection};
3	use std::path::Path;
4	use std::time::{SystemTime, UNIX_EPOCH};
5	
6	const MAX_ENTRIES: usize = 10_000;
7	const SESSION_TTL_SECS: u64 = 3600;
8	
9	pub struct DedupCache {
10	    conn: Connection,
11	    session_id: String,
12	}
13	
14	pub struct DedupResult {
15	    pub cache_hit: bool,
16	    pub content_hash: String,
17	    pub tokens_saved: u64,
18	    pub summary: Option<String>,
19	}
20	
21	impl DedupCache {
22	    pub fn open(db_path: &Path, session_id: &str) -> Result<Self> {
23	        let conn = Connection::open(db_path)?;
24	        conn.execute_batch(
25	            "PRAGMA journal_mode=WAL;
26	             PRAGMA synchronous=NORMAL;
27	             PRAGMA busy_timeout=5000;"
28	        )?;
29	        conn.execute_batch(
30	            "CREATE TABLE IF NOT EXISTS dedup_cache (
31	                content_hash TEXT PRIMARY KEY,
32	                file_path TEXT NOT NULL,
33	                mtime_ns INTEGER NOT NULL,
34	                byte_size INTEGER NOT NULL,
35	                token_count INTEGER NOT NULL,
36	                session_id TEXT NOT NULL,
37	                created_at INTEGER NOT NULL,
38	                last_hit_at INTEGER NOT NULL,
39	                hit_count INTEGER NOT NULL DEFAULT 1
40	            );"
41	        )?;
42	        Ok(Self {
43	            conn,
44	            session_id: session_id.to_string(),
45	        })
46	    }
47	
48	    pub fn lookup(
49	        &self,
50	        file_path: &str,
51	        current_mtime_ns: u64,
52	        content: &str,
53	    ) -> Result<DedupResult> {
54	        let hash = blake3::hash(content.as_bytes()).to_hex().to_string();
55	        let now = now_secs();
56	
57	        let row: Option<(i64, i64, String)> = self
58	            .conn
59	            .query_row(
60	                "SELECT token_count, mtime_ns, session_id FROM dedup_cache
61	                 WHERE content_hash = ?1",
62	                params![hash],
63	                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
64	            )
65	            .optional()?;
66	
67	        match row {
68	            Some((token_count, stored_mtime, stored_session))
69	                if stored_mtime as u64 == current_mtime_ns
70	                    && stored_session == self.session_id
71	                    && !is_expired(now, SESSION_TTL_SECS) =>
72	            {
73	                self.conn.execute(
74	                    "UPDATE dedup_cache SET last_hit_at = ?1, hit_count = hit_count + 1
75	                     WHERE content_hash = ?2",
76	                    params![now as i64, hash],
77	                )?;
78	                let summary = format!(
79	                    "File {} ({} tokens) read previously this session, unchanged.",
80	                    file_path, token_count
81	                );
82	                Ok(DedupResult {
83	                    cache_hit: true,
84	                    content_hash: hash,
85	                    tokens_saved: token_count as u64,
86	                    summary: Some(summary),
87	                })
88	            }
89	            _ => {
90	                let token_count = estimate_tokens(content);
91	                self.conn.execute(
92	                    "INSERT OR REPLACE INTO dedup_cache
93	                     (content_hash, file_path, mtime_ns, byte_size, token_count,
94	                      session_id, created_at, last_hit_at, hit_count)
95	                     VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?7, 1)",
96	                    params![
97	                        hash,
98	                        file_path,
99	                        current_mtime_ns as i64,
100	                        content.len() as i64,
101	                        token_count as i64,
102	                        self.session_id,
103	                        now as i64,
104	                    ],
105	                )?;
106	                self.evict_if_needed()?;
107	                Ok(DedupResult {
108	                    cache_hit: false,
109	                    content_hash: hash,
110	                    tokens_saved: 0,
111	                    summary: None,
112	                })
113	            }
114	        }
115	    }
116	
117	    pub fn invalidate_path(&self, file_path: &str) -> Result<u64> {
118	        let changes = self.conn.execute(
119	            "DELETE FROM dedup_cache WHERE file_path = ?1",
120	            params![file_path],
121	        )?;
122	        Ok(changes as u64)
123	    }
124	
125	    pub fn invalidate_session(&self) -> Result<u64> {
126	        let changes = self.conn.execute(
127	            "DELETE FROM dedup_cache WHERE session_id = ?1",
128	            params![self.session_id],
129	        )?;
130	        Ok(changes as u64)
131	    }
132	
133	    pub fn clear(&self) -> Result<u64> {
134	        let changes = self.conn.execute("DELETE FROM dedup_cache", [])?;
135	        Ok(changes as u64)
136	    }
137	
138	    pub fn entry_count(&self) -> Result<usize> {
139	        let count: i64 = self
140	            .conn
141	            .query_row("SELECT COUNT(*) FROM dedup_cache", [], |row| row.get(0))?;
142	        Ok(count as usize)
143	    }
144	
145	    fn evict_if_needed(&self) -> Result<()> {
146	        let count = self.entry_count()?;
147	        if count > MAX_ENTRIES {
148	            let to_remove = count - MAX_ENTRIES;
149	            self.conn.execute(
150	                "DELETE FROM dedup_cache WHERE content_hash IN (
151	                    SELECT content_hash FROM dedup_cache
152	                    ORDER BY last_hit_at ASC LIMIT ?1
153	                )",
