9	pub struct EventBuffer {
10	    conn: Connection,
11	}
12	
13	impl EventBuffer {
14	    pub fn open(db_path: &Path) -> Result<Self> {
15	        let conn = Connection::open(db_path)?;
16	        conn.execute_batch(
17	            "PRAGMA journal_mode=WAL;
18	             PRAGMA synchronous=NORMAL;
19	             PRAGMA busy_timeout=5000;"
20	        )?;
21	        conn.execute_batch(
22	            "CREATE TABLE IF NOT EXISTS event_buffer (
23	                id INTEGER PRIMARY KEY AUTOINCREMENT,
24	                created_at INTEGER NOT NULL,
25	                payload BLOB NOT NULL,
26	                consumed INTEGER NOT NULL DEFAULT 0
27	            );"
28	        )?;
29	        conn.execute_batch(
30	            "CREATE INDEX IF NOT EXISTS idx_event_buffer_consumed
31	             ON event_buffer(consumed, id);"
32	        )?;
33	        Ok(Self { conn })
34	    }
35	
36	    pub fn append(&self, event: &proto::Event) -> Result<i64> {
37	        let mut buf = Vec::with_capacity(event.encoded_len());
38	        event.encode(&mut buf)?;
39	        let now = now_ms();
40	        self.conn.execute(
41	            "INSERT INTO event_buffer (created_at, payload) VALUES (?1, ?2)",
42	            params![now as i64, buf],
43	        )?;
44	        Ok(self.conn.last_insert_rowid())
45	    }
46	
47	    pub fn consume_batch(&self, limit: usize) -> Result<Vec<(i64, proto::Event)>> {
48	        let mut stmt = self.conn.prepare(
49	            "SELECT id, payload FROM event_buffer
50	             WHERE consumed = 0 ORDER BY id ASC LIMIT ?1",
51	        )?;
52	        let rows = stmt.query_map(params![limit as i64], |row| {
53	            let id: i64 = row.get(0)?;
54	            let payload: Vec<u8> = row.get(1)?;
55	            Ok((id, payload))
56	        })?;
57	
58	        let mut events = Vec::new();
59	        for row in rows {
60	            let (id, payload) = row?;
61	            let event = proto::Event::decode(payload.as_slice())?;
62	            events.push((id, event));
63	        }
64	        Ok(events)
65	    }
66	
67	    pub fn mark_consumed(&self, ids: &[i64]) -> Result<u64> {
68	        if ids.is_empty() {
69	            return Ok(0);
70	        }
71	        let placeholders: Vec<String> = ids.iter().map(|_| "?".to_string()).collect();
72	        let sql = format!(
73	            "UPDATE event_buffer SET consumed = 1 WHERE id IN ({})",
74	            placeholders.join(",")
75	        );
76	        let params: Vec<Box<dyn rusqlite::types::ToSql>> =
77	            ids.iter().map(|id| Box::new(*id) as Box<dyn rusqlite::types::ToSql>).collect();
78	        let refs: Vec<&dyn rusqlite::types::ToSql> = params.iter().map(|p| p.as_ref()).collect();
79	        let changes = self.conn.execute(&sql, refs.as_slice())?;
80	        Ok(changes as u64)
81	    }
82	
83	    pub fn purge_consumed(&self) -> Result<u64> {
84	        let changes = self
85	            .conn
86	            .execute("DELETE FROM event_buffer WHERE consumed = 1", [])?;
87	        Ok(changes as u64)
88	    }
89	
90	    pub fn pending_count(&self) -> Result<usize> {
91	        let count: i64 = self.conn.query_row(
92	            "SELECT COUNT(*) FROM event_buffer WHERE consumed = 0",
93	            [],
94	            |row| row.get(0),
95	        )?;
96	        Ok(count as usize)
97	    }
98	}
99	
100	fn now_ms() -> u64 {
101	    SystemTime::now()
102	        .duration_since(UNIX_EPOCH)
103	        .unwrap_or_default()
104	        .as_millis() as u64
105	}
