63	impl TrackingDb {
64	    pub fn open(db_path: &Path) -> Result<Self> {
65	        let conn = Connection::open(db_path)?;
66	        conn.execute_batch(
67	            "PRAGMA journal_mode=WAL;
68	             PRAGMA synchronous=NORMAL;
69	             PRAGMA busy_timeout=5000;"
70	        )?;
71	        conn.execute_batch(
72	            "CREATE TABLE IF NOT EXISTS tracking_events (
73	                id INTEGER PRIMARY KEY AUTOINCREMENT,
74	                timestamp INTEGER NOT NULL,
75	                command TEXT NOT NULL,
76	                input_tokens INTEGER NOT NULL,
77	                output_tokens INTEGER NOT NULL,
78	                tokens_saved INTEGER NOT NULL,
79	                layer TEXT NOT NULL,
80	                project TEXT NOT NULL,
81	                session_id TEXT NOT NULL
82	            );"
83	        )?;
84	        conn.execute_batch(
85	            "CREATE INDEX IF NOT EXISTS idx_tracking_timestamp
86	             ON tracking_events(timestamp);"
87	        )?;
88	        Ok(Self { conn })
89	    }
90	
91	    pub fn record(&self, event: &TrackingEvent) -> Result<()> {
92	        let now = now_secs();
93	        self.conn.execute(
94	            "INSERT INTO tracking_events
95	             (timestamp, command, input_tokens, output_tokens, tokens_saved,
96	              layer, project, session_id)
97	             VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)",
98	            params![
99	                now as i64,
100	                event.command,
101	                event.input_tokens as i64,
102	                event.output_tokens as i64,
103	                event.tokens_saved as i64,
104	                event.layer.as_str(),
105	                event.project,
106	                event.session_id,
107	            ],
108	        )?;
109	        Ok(())
110	    }
111	
112	    pub fn stats(&self, days: Option<i64>) -> Result<Stats> {
113	        let days = days.unwrap_or(RETENTION_DAYS);
114	        let cutoff = now_secs() as i64 - (days * 86400);
115	
116	        let (total_input, total_output, total_saved, count): (i64, i64, i64, i64) = self
117	            .conn
118	            .query_row(
119	                "SELECT COALESCE(SUM(input_tokens),0), COALESCE(SUM(output_tokens),0),
120	                        COALESCE(SUM(tokens_saved),0), COUNT(*)
121	                 FROM tracking_events WHERE timestamp >= ?1",
122	                params![cutoff],
123	                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
124	            )?;
125	
126	        let savings_pct = if total_input > 0 {
127	            (total_saved as f64 / total_input as f64) * 100.0
128	        } else {
129	            0.0
130	        };
131	
132	        let mut top_stmt = self.conn.prepare(
133	            "SELECT command, SUM(tokens_saved) as saved, COUNT(*) as cnt
134	             FROM tracking_events WHERE timestamp >= ?1
135	             GROUP BY command ORDER BY saved DESC LIMIT 10",
136	        )?;
137	        let top_commands: Vec<CommandStats> = top_stmt
138	            .query_map(params![cutoff], |row| {
139	                Ok(CommandStats {
140	                    command: row.get(0)?,
141	                    saved: row.get::<_, i64>(1)? as u64,
142	                    count: row.get::<_, i64>(2)? as u64,
143	                })
144	            })?
145	            .filter_map(|r| r.ok())
146	            .collect();
147	
148	        let (comp_saved, dedup_saved): (i64, i64) = self.conn.query_row(
149	            "SELECT
150	                COALESCE(SUM(CASE WHEN layer='compression' THEN tokens_saved ELSE 0 END),0),
151	                COALESCE(SUM(CASE WHEN layer='dedup' THEN tokens_saved ELSE 0 END),0)
152	             FROM tracking_events WHERE timestamp >= ?1",
153	            params![cutoff],
154	            |row| Ok((row.get(0)?, row.get(1)?)),
155	        )?;
156	
157	        Ok(Stats {
158	            total_input_tokens: total_input as u64,
159	            total_output_tokens: total_output as u64,
160	            total_saved: total_saved as u64,
161	            savings_pct,
162	            event_count: count as u64,
163	            top_commands,
164	            by_layer: LayerStats {
165	                compression_saved: comp_saved as u64,
166	                dedup_saved: dedup_saved as u64,
167	            },
168	        })
169	    }
170	
171	    pub fn cleanup(&self) -> Result<u64> {
172	        let cutoff = now_secs() as i64 - (RETENTION_DAYS * 86400);
173	        let changes = self.conn.execute(
174	            "DELETE FROM tracking_events WHERE timestamp < ?1",
175	            params![cutoff],
176	        )?;
177	        Ok(changes as u64)
178	    }
179	}
