85	        Commands::Init { global } => hooks::install(global),
86	        Commands::Uninit { global } => hooks::uninstall(global),
87	        Commands::Wrap { command } => wrap::execute(&command),
88	        Commands::Stats { json, days } => stats::show(json, days),
89	        Commands::Cache { action } => handle_cache(action),
90	        Commands::Hook { action } => handle_hook(action),
