104	fn handle_cache(action: CacheAction) -> anyhow::Result<()> {
105	    let db_path = paths::db_path();
106	    match action {
107	        CacheAction::Clear => {
108	            if db_path.exists() {
109	                let cache = codeflow_core::dedup::DedupCache::open(&db_path, "")?;
110	                let removed = cache.clear()?;
111	                println!("Cleared {} cache entries.", removed);
112	            } else {
113	                println!("Cache is empty.");
114	            }
115	            Ok(())
116	        }
117	        CacheAction::Info => {
118	            if db_path.exists() {
119	                let cache = codeflow_core::dedup::DedupCache::open(&db_path, "")?;
120	                let count = cache.entry_count()?;
121	                println!("Cache entries: {}", count);
122	                println!("Database: {}", db_path.display());
123	            } else {
124	                println!("No cache database found.");
125	            }
126	            Ok(())
127	        }
128	    }
129	}
130	
131	fn handle_hook(action: HookAction) -> anyhow::Result<()> {
132	    match action {
133	        HookAction::PreToolUse => {
134	            // Read hook input from stdin, rewrite bash commands
135	            let input = read_stdin()?;
136	            let parsed: serde_json::Value = serde_json::from_str(&input)
137	                .unwrap_or_else(|_| serde_json::Value::Null);
138	
139	            if let Some(tool_input) = parsed.get("tool_input") {
140	                if let Some(command) = tool_input.get("command").and_then(|c| c.as_str()) {
141	                    if should_wrap(command) {
142	                        let codeflow_bin = std::env::current_exe()
143	                            .unwrap_or_default()
144	                            .to_string_lossy()
145	                            .to_string();
146	                        let rewritten = format!("{} wrap {}", codeflow_bin, command);
147	                        let response = serde_json::json!({
148	                            "tool_input": {
149	                                "command": rewritten
150	                            }
151	                        });
152	                        println!("{}", serde_json::to_string(&response)?);
153	                        return Ok(());
154	                    }
155	                }
156	            }
157	            // No rewrite needed — empty response means pass through
158	            println!("{{}}");
159	            Ok(())
160	        }
161	        HookAction::PostToolUse => {
162	            // PostToolUse: no-op for now, output already compressed by wrap
163	            println!("{{}}");
164	            Ok(())
165	        }
166	    }
167	}
168	
169	fn should_wrap(command: &str) -> bool {
170	    let first_word = command.split_whitespace().next().unwrap_or("");
171	    let wrappable = [
172	        "git", "npm", "npx", "pnpm", "yarn", "cargo", "pytest", "python",
173	        "tsc", "eslint", "ls", "find", "grep", "cat", "head", "tail",
174	        "docker", "kubectl", "go", "make", "pip", "ruff", "mypy",
175	    ];
176	    wrappable.iter().any(|w| first_word.ends_with(w) || first_word == *w)
177	}
178	
179	fn read_stdin() -> anyhow::Result<String> {
180	    use std::io::Read;
181	    let mut buf = String::new();
182	    std::io::stdin().read_to_string(&mut buf)?;
183	    Ok(buf)
184	}
