13	pub fn execute(command_args: &[String]) -> Result<()> {
14	    if command_args.is_empty() {
15	        anyhow::bail!("No command specified");
16	    }
17	
18	    let program = &command_args[0];
19	    let args = &command_args[1..];
20	
21	    let start = Instant::now();
22	    let raw_output = run_command(program, args)?;
23	    let session_id = session_id();
24	    let project_dir = std::env::current_dir()
25	        .unwrap_or_default()
26	        .to_string_lossy()
27	        .to_string();
28	
29	    let result = match compress(&raw_output, program, args, &session_id, &project_dir) {
30	        Ok(r) => r,
31	        Err(e) => {
32	            tracing::warn!("compression failed, passing through: {}", e);
33	            print_output(&raw_output);
34	            return Ok(());
35	        }
36	    };
37	
38	    let latency_ms = start.elapsed().as_secs_f64() * 1000.0;
39	    tracing::debug!(
40	        command = program,
41	        input_len = result.filter.input_len,
42	        output_len = result.filter.output_len,
43	        dedup_hit = result.dedup_hit,
44	        latency_ms = latency_ms,
45	        "wrap complete"
46	    );
47	
48	    if result.dedup_hit {
49	        if let Some(summary) = &result.dedup_summary {
50	            print_output(summary);
51	        } else {
52	            print_output(&result.filter.output);
53	        }
54	    } else {
55	        print_output(&result.filter.output);
56	    }
57	
58	    Ok(())
59	}
60	
61	struct WrapResult {
62	    filter: FilterResult,
63	    dedup_hit: bool,
64	    dedup_summary: Option<String>,
65	}
66	
67	fn compress(
68	    raw_output: &str,
69	    program: &str,
70	    args: &[String],
71	    session_id: &str,
72	    project_dir: &str,
73	) -> Result<WrapResult> {
74	    let data_dir = paths::data_dir();
75	    std::fs::create_dir_all(&data_dir)?;
76	    let db_path = paths::db_path();
77	
78	    let filters_dir = paths::filters_dir();
79	    let pipeline = FilterPipeline::load_from_dir(&filters_dir).unwrap_or_else(|_| FilterPipeline::new());
80	
81	    let filter_result = pipeline.apply(program, &args.iter().map(|s| s.to_string()).collect::<Vec<_>>(), raw_output);
82	
83	    let dedup_cache = DedupCache::open(&db_path, session_id)?;
84	    let content_to_check = &filter_result.output;
85	    let fake_mtime = file_content_mtime(content_to_check);
86	    let dedup_result = dedup_cache.lookup(
87	        &format!("cmd:{}:{}", program, args.join(" ")),
88	        fake_mtime,
89	        content_to_check,
90	    )?;
91	
92	    let tokens_saved_compress = if filter_result.filter_applied {
93	        estimate_tokens(filter_result.input_len) - estimate_tokens(filter_result.output_len)
94	    } else {
95	        0
96	    };
97	
98	    let tracking = TrackingDb::open(&db_path)?;
99	
100	    if filter_result.filter_applied && tokens_saved_compress > 0 {
101	        tracking.record(&TrackingEvent {
102	            command: program.to_string(),
103	            input_tokens: estimate_tokens(filter_result.input_len) as u64,
104	            output_tokens: estimate_tokens(filter_result.output_len) as u64,
105	            tokens_saved: tokens_saved_compress as u64,
106	            layer: SavingsLayer::Compression,
107	            project: project_dir.to_string(),
108	            session_id: session_id.to_string(),
109	        })?;
110	    }
111	
112	    if dedup_result.cache_hit {
113	        tracking.record(&TrackingEvent {
114	            command: program.to_string(),
115	            input_tokens: estimate_tokens(filter_result.output_len) as u64,
116	            output_tokens: 0,
117	            tokens_saved: dedup_result.tokens_saved,
118	            layer: SavingsLayer::Dedup,
119	            project: project_dir.to_string(),
120	            session_id: session_id.to_string(),
121	        })?;
122	    }
123	
124	    if let Ok(event_buf) = EventBuffer::open(&db_path) {
125	        let event = proto::Event {
126	            id: uuid::Uuid::new_v4().to_string(),
127	            timestamp_ms: chrono::Utc::now().timestamp_millis(),
128	            session_id: session_id.to_string(),
129	            project_dir: project_dir.to_string(),
130	            command: format!("{} {}", program, args.join(" ")),
131	            event_type: if dedup_result.cache_hit {
132	                proto::EventType::Dedup as i32
133	            } else {
134	                proto::EventType::Compression as i32
135	            },
136	            compression: Some(proto::CompressionEvent {
137	                input_bytes: filter_result.input_len as u64,
138	                output_bytes: filter_result.output_len as u64,
139	                input_tokens: estimate_tokens(filter_result.input_len) as u64,
140	                output_tokens: estimate_tokens(filter_result.output_len) as u64,
141	                tokens_saved: tokens_saved_compress as u64,
142	                filter_name: program.to_string(),
143	                compression_level: "default".to_string(),
144	                latency_ms: 0.0,
145	            }),
146	            dedup: if dedup_result.cache_hit {
147	                Some(proto::DedupEvent {
148	                    content_hash: dedup_result.content_hash.clone(),
149	                    cache_hit: true,
150	                    tokens_saved: dedup_result.tokens_saved,
151	                    file_path: String::new(),
152	                    latency_ms: 0.0,
153	                })
154	            } else {
155	                None
156	            },
157	        };
158	        let _ = event_buf.append(&event);
159	    }
160	
161	    Ok(WrapResult {
162	        filter: filter_result,
163	        dedup_hit: dedup_result.cache_hit,
164	        dedup_summary: dedup_result.summary,
165	    })
166	}
167	
168	fn run_command(program: &str, args: &[String]) -> Result<String> {
169	    let output = Command::new(program)
170	        .args(args)
171	        .output()
172	        .map_err(|e| anyhow::anyhow!("failed to execute {}: {}", program, e))?;
173	
174	    let mut combined = String::new();
175	    if !output.stdout.is_empty() {
176	        combined.push_str(&String::from_utf8_lossy(&output.stdout));
177	    }
178	    if !output.stderr.is_empty() {
179	        if !combined.is_empty() {
180	            combined.push('\n');
181	        }
182	        combined.push_str(&String::from_utf8_lossy(&output.stderr));
183	    }
184	    Ok(combined)
185	}
186	
187	fn print_output(text: &str) {
188	    let stdout = std::io::stdout();
189	    let mut handle = stdout.lock();
190	    let _ = handle.write_all(text.as_bytes());
191	    if !text.ends_with('\n') {
192	        let _ = handle.write_all(b"\n");
193	    }
194	    let _ = handle.flush();
195	}
196	
197	fn estimate_tokens(byte_len: usize) -> usize {
198	    (byte_len + 3) / 4
199	}
200	
201	fn file_content_mtime(content: &str) -> u64 {
202	    let hash = blake3::hash(content.as_bytes());
203	    let bytes = hash.as_bytes();
204	    u64::from_le_bytes(bytes[..8].try_into().unwrap_or([0; 8]))
205	}
206	
207	fn session_id() -> String {
208	    std::env::var("CLAUDE_SESSION_ID")
209	        .or_else(|_| std::env::var("CODEFLOW_SESSION_ID"))
210	        .unwrap_or_else(|_| {
211	            // Derive from parent PID for stable session within one Claude Code run
212	            format!("local-{}", std::process::id())
213	        })
214	}
