33	pub fn uninstall(global: bool) -> Result<()> {
34	    let claude_dir = paths::claude_hooks_dir();
35	    let settings_path = if global {
36	        claude_dir.join("settings.json")
37	    } else {
38	        Path::new(".claude").join("settings.json")
39	    };
40	
41	    if !settings_path.exists() {
42	        println!("No settings file found at {}", settings_path.display());
43	        return Ok(());
44	    }
45	
46	    let settings = std::fs::read_to_string(&settings_path)?;
47	    let mut json: serde_json::Value = serde_json::from_str(&settings)?;
48	
49	    if let Some(hooks) = json.get_mut("hooks") {
50	        if let Some(obj) = hooks.as_object_mut() {
51	            obj.remove("PreToolUse");
52	            obj.remove("PostToolUse");
53	            if obj.is_empty() {
54	                json.as_object_mut().unwrap().remove("hooks");
55	            }
56	        }
57	    }
58	
59	    let output = serde_json::to_string_pretty(&json)?;
60	    std::fs::write(&settings_path, output)?;
61	    println!("✓ CODEFLOW hooks removed from {}", settings_path.display());
62	
63	    Ok(())
64	}
