72	fn check_rtk_conflict(settings_path: &Path) -> Result<()> {
73	    if !settings_path.exists() {
74	        return Ok(());
75	    }
76	    let content = std::fs::read_to_string(settings_path)?;
77	    if content.contains("rtk") || content.contains("RTK") {
78	        eprintln!("⚠ Warning: Existing RTK hooks detected in {}", settings_path.display());
79	        eprintln!("  CODEFLOW will override RTK hooks. Remove RTK hooks manually if needed.");
80	    }
81	    Ok(())
82	}
