133	fn write_settings(path: &Path, content: &str) -> Result<()> {
134	    if let Some(parent) = path.parent() {
135	        std::fs::create_dir_all(parent)?;
136	    }
137	    std::fs::write(path, content)?;
138	    Ok(())
139	}
