24	        exe_dir.join("../../filters"),
25	        PathBuf::from("cli/filters"),
26	        PathBuf::from("filters"),
27	    ];
28	
29	    for c in &candidates {
30	        if c.exists() {
31	            return c.clone();
32	        }
33	    }
34	    exe_dir.join("filters")
35	}
